-- ════════════════════════════════════════════════════════════════════════
-- Hearthrise — THE LEVEL CURVE  (GENERATED — DO NOT EDIT)
--
--   Generated by tools/gen-level-curve.mjs from src/data/core-model.js LEVEL_CURVE
--   through src/core/xp.js levelCurveRows. Any hand edit FAILS
--   `node tools/gen-level-curve.mjs --check`.
--
-- WHAT: the character's Level curve as PACE BRACKETS (lane/b-level-curve, to Tyler's
-- balance ruling 2026-10-25 §2: L10 6 h, L25 36 h, L50 168 h ... L1000 23,520 h of
-- efficient hunting, held on the real engine by tools/balance-sim): from a bracket's
-- start Level the step to the next Level costs first + rise x m + bend x m^2 (m Levels
-- into the bracket). hr_level_curve holds 16 rows, rewritten whole. ROWS ONLY: the two
-- curve functions read this table and are not restated (hr_char_xp_for_level is LANGUAGE
-- plpgsql since 2027-02-11-settle-plan-cache-2.generated.sql: a SQL copy is re-planned on
-- every call on PostgreSQL 17), so every reader (the settle's death floor, hr_level_block,
-- hr_level_of, the analyzer's ETA) follows with no edit.
-- NEW IN THIS FILE (lane/c-levels-7-9, 2026-11-20; Tyler ruled balance call 27-2): the new player as
-- played (start kit, Hunt again in the Thicket) took 1.4 / 3.5 / 4.2 hours for Levels 7, 8 and 9 and
-- reached Level 10 at 10.6 h, where both light players quit. Steps 7-9 re-cut to 21,000 / 29,000 /
-- 34,002 XP (Level 10 at 6.0 h, none of Levels 1-15 over 4 h, tests/start-kit-pace.mjs); steps 10-20
-- take the XP back (the Glade's 16-20 most), and every step from 21 on costs what it did. EASED 2026-11-23
-- (lane/skills-time-parity): the combat skills on the Level clock leave a new player's skills near its Level,
-- so steps 11-15 cost 872 to 4,360 XP less (Level 15 -> 16 in 4.40 h, the red line 4.5) and every threshold
-- from Level 12 falls by up to 13,080 XP. Level 10 at 105733 XP, Level 50 at 17019187. LIVE CHARACTERS: nothing is
-- stored per Level, so a hero's Level is read from its Level XP. Only thresholds 8-20 move and all
-- fall: §2 holds every hero's Level as the rows this file replaces made it and refuses the whole file
-- if one would read LOWER (no Level is lost); a hero in a lowered gap reads its higher Level at once,
-- and a notice counts them.
-- ORDER: 1016 in its name, after 1015 (no table or function shared with 1009-1015). The hr-accrue deploy carrying the same
-- LEVEL_CURVE goes first, then this file at once: between the two a Level 8-20 hero's death is priced
-- on two curves and may be refused once as death_xp_over, then settles on the next tick.
-- No begin/commit (CLAUDE.md §2).
-- ════════════════════════════════════════════════════════════════════════

-- ── §0 PRECONDITIONS ─────────────────────────────────────────────────────────
do $mig$
begin
  if to_regprocedure('public.hr_char_level(bigint)') is null or to_regprocedure('public.hr_char_xp_for_level(integer)') is null then
    raise exception 'PRECONDITION: apply 2026-10-27-core-bodies.sql first (the curve functions this file feeds)'; end if;
  if (select l.lanname from pg_proc p join pg_language l on l.oid = p.prolang
       where p.oid = 'public.hr_char_xp_for_level(integer)'::regprocedure) <> 'plpgsql' then
    raise exception 'PRECONDITION: apply 2027-02-11-settle-plan-cache-2.generated.sql first (hr_char_xp_for_level as plpgsql)'; end if;
end $mig$;

-- ── §1 THE ROWS ──────────────────────────────────────────────────────────────
create table if not exists public.hr_level_curve (
  from_level int    primary key check (from_level >= 1),
  base_xp    bigint not null check (base_xp >= 0),
  first_xp   bigint not null check (first_xp >= 1),
  rise       bigint not null check (rise >= 0),
  bend       bigint not null check (bend >= 0),
  constraint hr_level_curve_rises_ck check (rise + bend >= 1)
);
alter table public.hr_level_curve enable row level security;
revoke all on public.hr_level_curve from public, anon, authenticated, service_role;

-- Every hero's Level on the rows this file replaces, held for §2's NO LIVE LEVEL MOVES (this session only, dropped after it).
drop table if exists pg_temp.hr_level_curve_held;
create temp table hr_level_curve_held as
  select s.user_id, s.slot, public.hr_char_level(s.level_xp) as lv from public.player_state s;

delete from public.hr_level_curve;
insert into public.hr_level_curve (from_level, base_xp, first_xp, rise, bend) values
  (1, 0, 210, 199, 0),
  (2, 210, 409, 389, 0),
  (3, 619, 798, 762, 0),
  (4, 1417, 1560, 4881, 0),
  (5, 2977, 6441, 5872, 0),
  (6, 9418, 12313, 8687, 0),
  (7, 21731, 21000, 8000, 0),
  (8, 42731, 29000, 5002, 0),
  (9, 71731, 34002, 30000, 0),
  (10, 105733, 64002, 3758, 0),
  (15, 463323, 82792, 78683, 0),
  (16, 546115, 161475, 300, 0),
  (21, 1356490, 162975, 14454, 657),
  (50, 17019187, 1134678, 78689, 162),
  (110, 235753417, 6439218, 70000, 100),
  (300, 2942886337, 23349218, 350000, 100);

-- ── §2 SELF-CHECK (CLAUDE.md §4) ──────────────────────────────────────────────
-- The rows are exactly the generated set; both functions answer the JS values at every pinned Level (bracket edges,
-- the target Levels, a deep one) and read back each boundary exactly (x - 1, x, the next total - 1); every step from
-- Level 1 to 3,000 costs more than the one before; the block a fresh hero projects is Level 1 needing the first step;
-- no live hero loses a Level; no client reaches the rows or the functions.
do $$
declare v_bad text; v_role text; v_up int;
begin
  if (select count(*) from public.hr_level_curve) <> 16
     or exists (select 1 from (values
  (1, 0, 210, 199, 0),
  (2, 210, 409, 389, 0),
  (3, 619, 798, 762, 0),
  (4, 1417, 1560, 4881, 0),
  (5, 2977, 6441, 5872, 0),
  (6, 9418, 12313, 8687, 0),
  (7, 21731, 21000, 8000, 0),
  (8, 42731, 29000, 5002, 0),
  (9, 71731, 34002, 30000, 0),
  (10, 105733, 64002, 3758, 0),
  (15, 463323, 82792, 78683, 0),
  (16, 546115, 161475, 300, 0),
  (21, 1356490, 162975, 14454, 657),
  (50, 17019187, 1134678, 78689, 162),
  (110, 235753417, 6439218, 70000, 100),
  (300, 2942886337, 23349218, 350000, 100)) d(from_level, base_xp, first_xp, rise, bend)
                 where not exists (select 1 from public.hr_level_curve k where k.from_level = d.from_level and k.base_xp = d.base_xp
                                     and k.first_xp = d.first_xp and k.rise = d.rise and k.bend = d.bend)) then
    raise exception 'level-curve: hr_level_curve is not the generated 16-row set'; end if;
  select string_agg(p.l || ': ' || public.hr_char_xp_for_level(p.l) || ' <> ' || p.x, ', ') into v_bad
    from (values (1, 0), (2, 210), (3, 619), (4, 1417), (5, 2977), (6, 9418), (7, 21731), (8, 42731), (9, 71731), (10, 105733), (11, 169735), (14, 384289), (15, 463323), (16, 546115), (17, 707590), (20, 1193815), (21, 1356490), (22, 1519465), (25, 2104312), (49, 15936412), (50, 17019187), (51, 18153865), (100, 176695962), (109, 229412166), (110, 235753417), (111, 242192635), (200, 1119529537), (299, 2919645019), (300, 2942886337), (301, 2966235555), (500, 14842399937), (750, 51836166937), (1000, 116323683937), (5000, 7437273955937)) p(l, x)
   where public.hr_char_xp_for_level(p.l) <> p.x;
  if v_bad is not null then raise exception 'level-curve: hr_char_xp_for_level disagrees with src/core/xp.js at %', v_bad; end if;
  select string_agg(p.l::text, ', ') into v_bad
    from (values (1, 0), (2, 210), (3, 619), (4, 1417), (5, 2977), (6, 9418), (7, 21731), (8, 42731), (9, 71731), (10, 105733), (11, 169735), (14, 384289), (15, 463323), (16, 546115), (17, 707590), (20, 1193815), (21, 1356490), (22, 1519465), (25, 2104312), (49, 15936412), (50, 17019187), (51, 18153865), (100, 176695962), (109, 229412166), (110, 235753417), (111, 242192635), (200, 1119529537), (299, 2919645019), (300, 2942886337), (301, 2966235555), (500, 14842399937), (750, 51836166937), (1000, 116323683937), (5000, 7437273955937)) p(l, x)
   where public.hr_char_level(p.x) <> p.l
      or (p.l > 1 and public.hr_char_level(p.x - 1) <> p.l - 1)
      or public.hr_char_level(public.hr_char_xp_for_level(p.l + 1) - 1) <> p.l;
  if v_bad is not null then raise exception 'level-curve: hr_char_level does not read back Level(s) %', v_bad; end if;
  /* NO LIVE LEVEL LOST (2026-11-19, the Coordinator's no-Level-loss route; 2026-11-20 lane/c-levels-7-9: a lowered threshold may lift a
     hero, it never drops one): every hero reads at least the Level on these rows that it read on the rows they replace. One hero who
     would read lower refuses the whole file; nothing applies. */
  select count(*)::text into v_bad from pg_temp.hr_level_curve_held h
    join public.player_state s on s.user_id = h.user_id and s.slot = h.slot
   where public.hr_char_level(s.level_xp) < h.lv;
  if v_bad <> '0' then raise exception 'level-curve: % live hero(es) would lose a Level on these rows; nothing applied', v_bad; end if;
  select count(*) into v_up from pg_temp.hr_level_curve_held h
    join public.player_state s on s.user_id = h.user_id and s.slot = h.slot
   where public.hr_char_level(s.level_xp) > h.lv;
  raise notice 'level-curve: % live hero(es) read a higher Level on these rows', v_up;
  select string_agg(s.l::text, ', ') into v_bad from (
    select l, public.hr_char_xp_for_level(l + 1) - public.hr_char_xp_for_level(l) as step,
           lag(public.hr_char_xp_for_level(l + 1) - public.hr_char_xp_for_level(l)) over (order by l) as before
      from generate_series(1, 3000) l) s
   where s.step < 1 or s.step <= s.before;
  if v_bad is not null then raise exception 'level-curve: the step to Level(s) % does not cost more than the one before', v_bad; end if;
  if public.hr_level_block(0) <> jsonb_build_object('xp', 0, 'level', 1, 'into', 0, 'need', 210) then
    raise exception 'level-curve: a fresh hero does not project Level 1 needing % XP', 210; end if;
  foreach v_role in array array['anon', 'authenticated'] loop
    if has_table_privilege(v_role, 'public.hr_level_curve', 'select,insert,update,delete')
       or has_function_privilege(v_role, 'public.hr_char_level(bigint)', 'execute')
       or has_function_privilege(v_role, 'public.hr_char_xp_for_level(integer)', 'execute') then
      raise exception 'level-curve: % reaches the curve', v_role; end if;
  end loop;
end $$;
drop table pg_temp.hr_level_curve_held;
